-- PROJECT-NO-WORK-1 (2026-11-05, charter pillar autonomy, program QNFO.OPS; cluster C8-PROJECTS-GOALS of the roadmap and backlog completion sweep).
-- Read 2026-11-05 01:20Z: 71 roadmap rows PROJ-<project> (source projects) were open. The portfolio loops already close the ones that have worked: portfolio-execute sets a project completed when it has
-- mapped issues, all of them closed, and the roadmap loop verifies the row (16 rows of retired projects verified this hour; 5 more projects, W.qnfo-github-steward, W.qnfo-intent-orchestrator,
-- W.qnfo-subscribers, W.radar-hub and W.personal-watch, have 0 open mapped issues and complete on the next :50 tick). 42 projects have open mapped work (W.qnfo-fleet-control 271, W.qnfo-fleet-dashboard 40,
-- W.qnfo-ops 27, ... 1): they are ongoing and stay open with their issue counts. The remaining 24 are derived registry entries that NEVER had an issue mapped (18 repositories R.* and 6 workers:
-- W.qnfo-containers-pilot, W.qnfo-evolve, W.qnfo-fleet-lee, W.qnfo-ipatent, W.qnfo-tools-mcp, W.voice-stt), 23 of them older than 14 days: no loop can complete them (completion needs mapped work) and no work exists to do, so the
-- row stays open for ever without describing anything. This file retires those rows (the projects stay active in `projects`, nothing about the project changes) and adds the standing rule as a
-- two-step fleet task, so the row reopens by itself when an issue maps to the project and any new derived project without work is handled the same way after 14 days. W.qnfo-fleet-lee (5 days old) waits its grace.
-- Revert: the Rollback header (rows restored from bak_20261105_c8_proj_rows; the task and cron removed); stop without a deploy: UPDATE fleet_crons SET enabled = 0 WHERE name = 'roadmap-project-nowork-hourly'.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- BACKUP: bak_20261105_c8_proj_rows
-- Rollback: UPDATE roadmap_implementation SET status = (SELECT b.status FROM bak_20261105_c8_proj_rows b WHERE b.id = roadmap_implementation.id), evidence = (SELECT b.evidence FROM bak_20261105_c8_proj_rows b WHERE b.id = roadmap_implementation.id), verified_at = (SELECT b.verified_at FROM bak_20261105_c8_proj_rows b WHERE b.id = roadmap_implementation.id) WHERE id IN (SELECT id FROM bak_20261105_c8_proj_rows); DELETE FROM fleet_crons WHERE name = 'roadmap-project-nowork-hourly'; DELETE FROM fleet_tasks WHERE id = 'roadmap-project-nowork'
-- CAUSE-MAPPED: no metric is registered here.

CREATE TABLE IF NOT EXISTS bak_20261105_c8_proj_rows AS SELECT * FROM roadmap_implementation WHERE item LIKE 'PROJ-%' AND status = 'open';

INSERT OR IGNORE INTO fleet_tasks (id, name, type, definition, timeout_ms, retries, version, enabled, updated_at)
VALUES ('roadmap-project-nowork', 'PROJECT-NO-WORK-1: roadmap rows of derived projects that never had work retire; they reopen when an issue maps', 'workflow', '{"steps": [{"type": "sql", "name": "project-nowork-retire", "db": "AUDIT", "sql": "UPDATE roadmap_implementation SET status = ''retired'', verified_at = datetime(''now''), evidence = ''PROJECT-NO-WORK-1: project '' || artifact_ref || '' is a derived registry entry with no issue ever mapped to it (issue_project_map holds 0 rows for it) and is older than 14 days; a registry entry with no work item is not a roadmap deliverable. The row reopens by itself when an issue maps to the project.'' WHERE item LIKE ''PROJ-%'' AND status = ''open'' AND EXISTS (SELECT 1 FROM projects p WHERE p.project_code = roadmap_implementation.artifact_ref AND p.status = ''active'' AND p.source = ''derived'' AND p.project_code NOT LIKE ''W.QNFO.%'' AND p.created_at < datetime(''now'', ''-14 days'') AND NOT EXISTS (SELECT 1 FROM issue_project_map m WHERE m.project_code = p.project_code))"}, {"type": "sql", "name": "project-nowork-reopen", "db": "AUDIT", "sql": "UPDATE roadmap_implementation SET status = ''open'', verified_at = NULL, evidence = ''PROJECT-NO-WORK-1: reopened, an issue is now mapped to project '' || artifact_ref WHERE item LIKE ''PROJ-%'' AND status = ''retired'' AND evidence LIKE ''PROJECT-NO-WORK-1: project%'' AND EXISTS (SELECT 1 FROM issue_project_map m WHERE m.project_code = roadmap_implementation.artifact_ref)"}]}', 120000, 1, 1, 1, strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO fleet_crons (name, cron_expr, task_id, enabled, timezone, next_fire, updated_at)
SELECT 'roadmap-project-nowork-hourly', '35 * * * *', 'roadmap-project-nowork', 1, 'UTC', NULL, strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE EXISTS (SELECT 1 FROM fleet_tasks WHERE id = 'roadmap-project-nowork');

-- The rule once, now (the task runs it hourly from the next :35).
UPDATE roadmap_implementation SET status = 'retired', verified_at = datetime('now'), evidence = 'PROJECT-NO-WORK-1: project ' || artifact_ref || ' is a derived registry entry with no issue ever mapped to it (issue_project_map holds 0 rows for it) and is older than 14 days; a registry entry with no work item is not a roadmap deliverable. The row reopens by itself when an issue maps to the project.' WHERE item LIKE 'PROJ-%' AND status = 'open' AND EXISTS (SELECT 1 FROM projects p WHERE p.project_code = roadmap_implementation.artifact_ref AND p.status = 'active' AND p.source = 'derived' AND p.project_code NOT LIKE 'W.QNFO.%' AND p.created_at < datetime('now', '-14 days') AND NOT EXISTS (SELECT 1 FROM issue_project_map m WHERE m.project_code = p.project_code));
